import heapq
from bisect import bisect_right
from typing import List, Optional

DAY_MS = 24 * 60 * 60 * 1000

class BankingSystem:
    def __init__(self):
        self.acc = {}        # aid -> {"bal", "out", "hist": [(ts, bal)]}
        self.pending = {}    # tid -> {"src", "dst", "amt"}
        self.expiry = []     # (过期时刻, 序号, tid)
        self.seq = 0

    def _record(self, aid, ts):
        a = self.acc[aid]
        if a["hist"][-1][0] == ts:
            a["hist"][-1] = (ts, a["bal"])
        else:
            a["hist"].append((ts, a["bal"]))

    def _expire(self, ts):
        # 超过 24 小时没被接受的转账，把冻结的钱退回给转出方
        while self.expiry and self.expiry[0][0] <= ts:
            when, _, tid = heapq.heappop(self.expiry)
            t = self.pending.pop(tid, None)
            if t and t["src"] in self.acc:
                self.acc[t["src"]]["bal"] += t["amt"]
                self._record(t["src"], when)

    def create_account(self, ts: int, aid: str) -> bool:
        self._expire(ts)
        if aid in self.acc:
            return False
        self.acc[aid] = {"bal": 0, "out": 0, "hist": [(ts, 0)]}
        return True

    def deposit(self, ts: int, aid: str, amt: int) -> Optional[int]:
        self._expire(ts)
        if aid not in self.acc:
            return None
        self.acc[aid]["bal"] += amt
        self._record(aid, ts)
        return self.acc[aid]["bal"]

    def pay(self, ts: int, aid: str, amt: int) -> Optional[int]:
        self._expire(ts)
        if aid not in self.acc or self.acc[aid]["bal"] < amt:
            return None
        a = self.acc[aid]
        a["bal"] -= amt
        a["out"] += amt
        self._record(aid, ts)
        return a["bal"]

    def top_activity(self, ts: int, n: int) -> List[str]:
        self._expire(ts)
        top = sorted(self.acc.items(), key=lambda kv: (-kv[1]["out"], kv[0]))[:n]
        return [f"{aid}({a['out']})" for aid, a in top]

    def transfer(self, ts: int, src: str, dst: str, amt: int) -> Optional[str]:
        self._expire(ts)
        if src == dst or src not in self.acc or dst not in self.acc:
            return None
        if self.acc[src]["bal"] < amt:
            return None
        self.acc[src]["bal"] -= amt               # 发起即冻结
        self._record(src, ts)
        self.seq += 1
        tid = f"transfer{self.seq}"
        self.pending[tid] = {"src": src, "dst": dst, "amt": amt}
        heapq.heappush(self.expiry, (ts + DAY_MS + 1, self.seq, tid))   # ts + 24h 时仍可接受
        return tid

    def accept_transfer(self, ts: int, aid: str, tid: str) -> bool:
        self._expire(ts)
        t = self.pending.get(tid)
        if t is None or t["dst"] != aid:
            return False
        del self.pending[tid]
        self.acc[t["src"]]["out"] += t["amt"]     # 接受后才计入转出量
        self.acc[aid]["bal"] += t["amt"]
        self._record(aid, ts)
        return True

    def merge_accounts(self, ts: int, a1: str, a2: str) -> bool:
        self._expire(ts)
        if a1 == a2 or a1 not in self.acc or a2 not in self.acc:
            return False
        x, y = self.acc[a1], self.acc[a2]
        x["bal"] += y["bal"]
        x["out"] += y["out"]
        for tid, t in list(self.pending.items()):
            if {t["src"], t["dst"]} == {a1, a2}:
                x["bal"] += t["amt"]              # 两个账户之间的待处理转账直接作废退回
                del self.pending[tid]
                continue
            if t["src"] == a2:
                t["src"] = a1
            if t["dst"] == a2:
                t["dst"] = a1
        del self.acc[a2]
        self._record(a1, ts)
        return True

    def get_balance(self, ts: int, aid: str, time_at: int) -> Optional[int]:
        self._expire(ts)
        if aid not in self.acc:
            return None
        hist = self.acc[aid]["hist"]
        i = bisect_right(hist, (time_at, float("inf"))) - 1
        return hist[i][1] if i >= 0 else None
